// ====== غيّر أرقامك هنا ======
const fabrics = {
  cotton:         { name_ar: "قطن",          name_en: "Cotton",         base_price: 180 },
  twill:          { name_ar: "توين",          name_en: "Twill",          base_price: 220 },
  gabardine:      { name_ar: "جبردين",        name_en: "Gabardine",      base_price: 210 },
  polyester_mix:  { name_ar: "قطن مخلوط",     name_en: "Poly-cotton mix", base_price: 160 }
};

const logoPricePerLogo = 25;
const logoPlacementExtra = { chest: 0, back: 15, sleeve: 10 };

// كل صف هنا: أقل عدد قطع تبدأ منه الخصم، ونسبة الخصم
const quantityTiers = [
  { min_qty: 1,    discount_percent: 0 },
  { min_qty: 50,   discount_percent: 5 },
  { min_qty: 100,  discount_percent: 10 },
  { min_qty: 300,  discount_percent: 15 },
  { min_qty: 1000, discount_percent: 20 }
];
// ====== لغاية هنا بس اللي تغيره عادة ======

const body = $input.first().json.body || $input.first().json;
const quantity = Number(body.quantity) || 1;
const fabricId = body.fabricId || 'cotton';
const logoCount = Number(body.logoCount) || 0;
const logoPlacement = body.logoPlacement || 'chest';
const lang = body.lang || 'ar';

const fabric = fabrics[fabricId] || fabrics.cotton;
const extra = logoPlacementExtra[logoPlacement] ?? 0;
const perPieceBeforeDiscount = fabric.base_price + logoCount * (logoPricePerLogo + extra);

const tier = quantityTiers
  .slice()
  .sort((a, b) => a.min_qty - b.min_qty)
  .filter(t => quantity >= t.min_qty)
  .pop() || quantityTiers[0];

const perPiece = Math.round(perPieceBeforeDiscount * (1 - tier.discount_percent / 100));
const total = perPiece * quantity;

// توصية بسيطة — غيّر أو زوّد الشروط زي ما يناسبك
let recommendation_ar = '';
if (quantity >= 300 && fabricId !== 'polyester_mix') {
  recommendation_ar = 'بما إن العدد كبير، خامة القطن المخلوط ممكن توفرلك في التكلفة الإجمالية من غير ما تأثر كتير على الجودة.';
} else if (fabricId === 'twill') {
  recommendation_ar = 'توين اختيار قوي ومتين، مناسب جدًا للاستخدام اليومي المكثف.';
} else if (fabricId === 'gabardine') {
  recommendation_ar = 'جبردين بيدي مظهر رسمي أنيق، مناسب لقطاعات زي الفنادق والشركات.';
} else if (fabricId === 'cotton') {
  recommendation_ar = 'القطن مريح وتنفسه عالي، اختيار موفق للأجواء الحارة والمطاعم.';
}

return [{
  json: {
    fabric_name_ar: fabric.name_ar,
    fabric_name_en: fabric.name_en,
    per_piece_price: perPiece,
    quantity,
    total_price: total,
    discount_percent: tier.discount_percent,
    currency: 'EGP',
    recommendation_ar
  }
}];
